    void call(String action,JSONObject args,Done done,Button sending){
        String auth=token;if(sending!=null)sending.setEnabled(false);if(progress!=null)progress.setVisibility(View.VISIBLE);
        io.execute(()->{try{JSONObject result=api.call(action,args,auth);main.post(()->{if(isDestroyed()||!auth.equals(token))return;if(progress!=null)progress.setVisibility(View.GONE);if(sending!=null)sending.setEnabled(true);done.accept(result);});}
        catch(Exception ex){main.post(()->{if(isDestroyed()||!auth.equals(token))return;if(progress!=null)progress.setVisibility(View.GONE);if(sending!=null)sending.setEnabled(true);if(ex instanceof ParentApi.Failure&&((ParentApi.Failure)ex).unauthorized){clearSession();login(false);toast("Sesi berakhir. Silakan masuk kembali.");}else error(ex);});}});
    }
