    void otp(){
        int generation=++epoch;base("Verifikasi WhatsApp",false);
        LinearLayout c=card("Cek WhatsApp Anda","Masukkan 6 digit kode yang dikirim ke "+otpPhone+".");
        gap(c,20);EditText code=input(this,"• • • • • •",InputType.TYPE_CLASS_NUMBER);code.setTextSize(26);code.setLetterSpacing(.25f);code.setGravity(Gravity.CENTER);code.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6)});c.addView(code);
        Button verify=button(this,"Verifikasi dan masuk  →",true,()->{});verify.setOnClickListener(v->{String value=code.getText().toString();if(value.length()!=6){code.setError("Masukkan 6 digit kode");return;}call("verify_otp",j("phone",otpPhone,"otp",value),this::authenticated,verify);});gap(c,16);c.addView(verify,new LinearLayout.LayoutParams(-1,dp(this,54)));
        label(c,"Jangan bagikan kode ini kepada siapa pun, termasuk pihak yang mengatasnamakan sekolah.");
        action(c,"Ganti nomor WhatsApp",false,()->login(true));
        Button resend=button(this,"Kirim ulang kode",false,()->{});resend.setOnClickListener(v->call("request_otp",j("phone",otpPhone),r->{otpPhone=s(r,"phone");otp();},resend));add(resend);
        long availableAt=SystemClock.elapsedRealtime()+60000;main.post(new Runnable(){public void run(){if(generation!=epoch||isDestroyed())return;long remaining=Math.max(0,(availableAt-SystemClock.elapsedRealtime()+999)/1000);resend.setEnabled(remaining==0);resend.setText(remaining>0?"Kirim ulang dalam "+remaining+" detik":"Kirim ulang kode");if(remaining>0)main.postDelayed(this,1000);}});
    }
