    void invoices(JSONObject d,boolean cached){
        JSONArray a=arr(d,"invoices");if(a.length()==0){JSONArray pending=arr(d,"aktif"),paid=arr(d,"lunas");for(int i=0;i<pending.length();i++)a.put(pending.opt(i));for(int i=0;i<paid.length();i++)a.put(paid.opt(i));}
        double due=0;int unpaid=0;for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i);if(!"paid".equals(s(r,"status"))){due+=Math.max(0,number(r,"total_amount")-number(r,"installment_paid_amount"));unpaid++;}}
        LinearLayout summary=card(rupiah(due),unpaid+" tagihan belum lunas");if(cached)label(summary,"Data tersimpan. Pembayaran tersedia setelah pemeriksaan terbaru selesai.");
        JSONArray rows=a;list(rows,r->{boolean paid="paid".equals(s(r,"status"));String label=s(r,"period_label");if(label.isEmpty())label=s(r,"invoice_number");LinearLayout c=card(label,s(r,"invoice_number"));badge(c,s(r,"status"));label(c,rupiah(number(r,"total_amount")));label(c,"Jatuh tempo: "+date(s(r,"due_date")));double partial=number(r,"installment_paid_amount");if(partial>0)label(c,"Sudah dicicil: "+rupiah(partial));if(paid){label(c,"Dibayar "+date(s(r,"paid_at")));action(c,"Unduh bukti pembayaran PDF",false,()->invoicePdf(r));if(s(r,"id").equals(pendingPayment)){pendingPayment="";toast("Pembayaran telah tervalidasi oleh sekolah");}}
            else {Button pay=button(this,"Bayar tagihan",true,()->payment(r,0));pay.setEnabled(!cached);gap(c,12);c.addView(pay,new LinearLayout.LayoutParams(-1,dp(this,50)));if(r.optBoolean("allow_installment")&&!"spp".equals(s(r,"bill_type")))action(c,"Cicilan & riwayat",false,()->installments(r));action(c,"Unduh rincian tagihan PDF",false,()->invoicePdf(r));}
        });
        if(!pendingPayment.isEmpty()&&!cached&&paymentChecks<8&&foreground){main.removeCallbacks(paymentPoll);main.postDelayed(paymentPoll,20000);}
    }
    final Runnable paymentPoll=()->{if(foreground&&screen.equals("spp")&&!pendingPayment.isEmpty()&&paymentChecks++<8)load(true);};
    void installments(JSONObject invoice){call("installment_list",j("student_id",studentId,"invoice_id",s(invoice,"id")),r->{epoch++;base("Cicilan tagihan",true);LinearLayout summary=card(s(invoice,"period_label"),s(invoice,"invoice_number"));label(summary,"Lunas: "+rupiah(number(r,"paid_amount")));label(summary,"Menunggu pembayaran: "+rupiah(number(r,"pending_amount")));label(summary,"Dapat dicicil: "+rupiah(number(r,"remaining")));if(number(r,"remaining")>0){EditText amount=input(this,"Nominal cicilan (Rp)",InputType.TYPE_CLASS_NUMBER);add(amount);Button create=button(this,"Pilih metode pembayaran",true,()->{try{long value=Long.parseLong(amount.getText().toString());if(value<1000||value>number(r,"remaining")){amount.setError("Masukkan nominal Rp1.000 hingga sisa tagihan");return;}payment(invoice,value);}catch(Exception e){amount.setError("Masukkan nominal cicilan");}});add(create);}list(arr(r,"installments"),row->{LinearLayout c=card(rupiah(number(row,"amount")),date(s(row,"created_at")));badge(c,s(row,"status"));if("pending".equals(s(row,"status"))&&!s(row,"mayar_payment_url").isEmpty())action(c,"Lanjutkan pembayaran",false,()->{pendingPayment=s(invoice,"id");paymentChecks=0;open(s(row,"mayar_payment_url"));});});},null);}
    void payment(JSONObject invoice,long amount){if(preparingPayment)return;preparingPayment=true;call("payment_config",j(),cfg->{preparingPayment=false;String[] channels={"qris","va","retail"};JSONObject fees=obj(cfg,"fees");double bill=amount>0?amount:Math.max(0,number(invoice,"total_amount")-number(invoice,"installment_paid_amount"));String[] choices={"QRIS","Virtual account / transfer bank","Retail / minimarket"};new AlertDialog.Builder(this).setTitle("Pilih metode pembayaran").setItems(choices,(dialog,index)->{String channel=channels[index];double estimate=channel.equals("qris")?Math.max(fees.optDouble("qris",3000),Math.round(bill*cfg.optDouble("qris_percent",0.01))):number(fees,channel);new AlertDialog.Builder(this).setTitle(choices[index]).setMessage("Tagihan: "+rupiah(bill)+"\nPerkiraan biaya layanan: "+rupiah(estimate)+"\n\nBiaya akhir akan ditampilkan sebelum melanjutkan ke penyedia pembayaran.").setNegativeButton("Batal",null).setPositiveButton("Buat pembayaran",(d,w)->{if(preparingPayment)return;preparingPayment=true;JSONObject args=j("student_id",studentId,"invoice_id",s(invoice,"id"),"channel",channel);String action="spp_pay";if(amount>0){action="spp_pay_installment";try{args.put("amount",amount);}catch(Exception ignored){}}call(action,args,result->{preparingPayment=false;String url=s(result,"payment_url");if(url.isEmpty()){alert("Belum dapat membayar","Tautan pembayaran tidak tersedia.");return;}double actual=number(result,"total_charged");new AlertDialog.Builder(this).setTitle("Pembayaran siap").setMessage("Total: "+rupiah(actual)+"\nBiaya layanan: "+rupiah(number(result,"service_fee"))+"\n\nAnda akan melanjutkan ke halaman resmi pembayaran melalui browser. Status lunas hanya mengikuti konfirmasi server.").setNegativeButton("Nanti",null).setPositiveButton("Lanjut pembayaran",(confirm,which)->{pendingPayment=s(invoice,"id");paymentChecks=0;screen="spp";open(url);}).show();},null);}).show();}).show();},null);}
    String formattedCard(String value){return value.isEmpty()?"Belum diterbitkan":value.replaceAll("(.{4})(?!$)","$1 ");}
    Bitmap studentQr(JSONObject student,int size) throws Exception {String value=s(student,"qr_code");if(value.isEmpty())value=s(student,"student_id");if(value.isEmpty())value=s(student,"id");if(value.isEmpty())throw new IOException("Identitas QR belum tersedia");Map<EncodeHintType,Object> hints=new EnumMap<>(EncodeHintType.class);hints.put(EncodeHintType.MARGIN,4);BitMatrix matrix=new MultiFormatWriter().encode(value,BarcodeFormat.QR_CODE,size,size,hints);Bitmap bitmap=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);int[] pixels=new int[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=matrix.get(x,y)?0xFF0F172A:Color.WHITE;bitmap.setPixels(pixels,0,size,0,0,size,size);return bitmap;}
    void savePng(Bitmap bitmap,String filename){try{ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);export(out.toByteArray(),"image/png",filename);}catch(Exception e){error(e);}}
