    void invoicePdf(JSONObject invoice){call("school_info",j("student_id",studentId),school->{try{PdfDocument pdf=new PdfDocument();PdfDocument.Page page=pdf.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas c=page.getCanvas();Paint p=new Paint(3);c.drawColor(Color.WHITE);p.setColor(BLUE);c.drawRect(0,0,595,12,p);p.setColor(INK);p.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));p.setTextSize(27);c.drawText("ATSkolla Parent",44,66,p);p.setTextSize(14);c.drawText("paid".equals(s(invoice,"status"))?"BUKTI PEMBAYARAN":"RINCIAN TAGIHAN",44,96,p);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(12);String[] lines={s(obj(school,"school"),"name"),s(obj(school,"school"),"address"),"", "Invoice: "+s(invoice,"invoice_number"),"Siswa: "+s(child(),"name"),"Kelas: "+s(child(),"class"),"Periode: "+s(invoice,"period_label"),"Jatuh tempo: "+date(s(invoice,"due_date")),"Status: "+s(invoice,"status"),"Dibayar: "+date(s(invoice,"paid_at")),"Metode: "+s(invoice,"payment_method"),"", "Pokok tagihan: "+rupiah(number(invoice,"amount")),"Denda: "+rupiah(number(invoice,"denda")),"Total tagihan: "+rupiah(number(invoice,"total_amount")),"Cicilan diterima: "+rupiah(number(invoice,"installment_paid_amount")),"", "Biaya layanan penyedia pembayaran dapat tercantum terpisah.","Status mengikuti data terakhir yang diterima aplikasi.","Dicetak "+date(day().toString())};int y=134;for(String line:lines){for(String part:wrap(line,p,505)){c.drawText(part,44,y,p);y+=19;}}pdf.finishPage(page);ByteArrayOutputStream out=new ByteArrayOutputStream();pdf.writeTo(out);pdf.close();export(out.toByteArray(),"application/pdf",s(invoice,"invoice_number").replaceAll("[^A-Za-z0-9-]","-")+".pdf");}catch(Exception e){error(e);}},null);}
    static List<String> wrap(String text,Paint p,int width){List<String> lines=new ArrayList<>();StringBuilder current=new StringBuilder();for(String word:text.split(" ")){if(p.measureText(current+" "+word)>width&&current.length()>0){lines.add(current.toString());current.setLength(0);}if(current.length()>0)current.append(' ');current.append(word);}lines.add(current.toString());return lines;}
    void export(byte[] data,String mime,String filename){pendingDocument=data;Intent save=new Intent(Intent.ACTION_CREATE_DOCUMENT);save.addCategory(Intent.CATEGORY_OPENABLE);save.setType(mime);save.putExtra(Intent.EXTRA_TITLE,filename);startActivityForResult(save,700);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null){if(request==700)pendingDocument=null;return;}Uri uri=data.getData();if(request==700&&pendingDocument!=null){byte[] bytes=pendingDocument;pendingDocument=null;io.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Tidak dapat menyimpan berkas");out.write(bytes);main.post(()->toast("Berkas berhasil disimpan"));}catch(Exception e){main.post(()->error(e));}});}else if(request==701){final int generation=epoch;final String auth=token;final String mime=getContentResolver().getType(uri);if(!Arrays.asList("image/jpeg","image/png","image/webp","application/pdf").contains(mime)){toast("Pilih JPG, PNG, WebP atau PDF");return;}if(attachmentLabel!=null)attachmentLabel.setText("Mengunggah lampiran…");io.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Berkas tidak dapat dibuka");ByteArrayOutputStream buffer=new ByteArrayOutputStream();byte[] part=new byte[8192];int n;while((n=in.read(part))!=-1){if(buffer.size()+n>5*1024*1024)throw new IOException("Lampiran maksimal 5 MB");buffer.write(part,0,n);}String ext=mime.equals("application/pdf")?".pdf":mime.equals("image/png")?".png":mime.equals("image/webp")?".webp":".jpg";String url=api.upload(buffer.toByteArray(),mime,ext,auth);main.post(()->{if(generation!=epoch||!auth.equals(token))return;attachment=url;if(attachmentLabel!=null)attachmentLabel.setText("Lampiran berhasil diunggah");});}catch(Exception e){main.post(()->{if(generation==epoch){if(attachmentLabel!=null)attachmentLabel.setText("Lampiran belum terunggah");error(e);}});}});}}
    void open(String url){try{Uri uri=Uri.parse(url);if(!Arrays.asList("https","tel","mailto").contains(uri.getScheme())){toast("Tautan tidak didukung");return;}startActivity(new Intent(Intent.ACTION_VIEW,uri).addCategory(Intent.CATEGORY_BROWSABLE));}catch(ActivityNotFoundException e){toast("Aplikasi untuk membuka tautan belum tersedia");}}
    void back(){if(!token.isEmpty()&&!screen.equals("home")){navigate("home");return;}finish();}
    // API 33+ is handled by the registered native OnBackInvokedCallback; this override is only for API 26–32.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){back();}
    void notificationSettings(){new AlertDialog.Builder(this).setTitle("Notifikasi pengumuman sekolah")
        .setMessage("Aktifkan pemeriksaan pengumuman berkala. Android menentukan waktu pemeriksaan (minimal sekitar 15 menit dan dapat lebih lama saat hemat baterai). Ini bukan push real-time. Isi notifikasi tidak menampilkan data pribadi siswa. Anda dapat menonaktifkannya kapan saja.")
        .setNegativeButton("Nonaktifkan",(d,w)->{ParentNotificationJob.disable(this);toast("Notifikasi dinonaktifkan");})
        .setPositiveButton("Aktifkan",(d,w)->{if(Build.VERSION.SDK_INT>=33&&!ParentNotificationJob.allowed(this))requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},810);else enableAnnouncements();}).show();}
    void enableAnnouncements(){try{ParentNotificationJob.enable(this);toast("Pemeriksaan pengumuman diaktifkan");}catch(Exception e){error(e);}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==810){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)enableAnnouncements();else toast("Notifikasi tidak diaktifkan. Pengumuman tetap tersedia di aplikasi.");}}
    private final Runnable foregroundRefresh=new Runnable(){public void run(){if(foreground&&!token.isEmpty()&&Arrays.asList("home","info").contains(screen))load(true);if(foreground)main.postDelayed(this,60000);}};
    @Override protected void onResume(){super.onResume();foreground=true;main.removeCallbacks(foregroundRefresh);main.postDelayed(foregroundRefresh,60000);ParentNotificationJob.schedule(this);if(!pendingPayment.isEmpty()&&!token.isEmpty()){screen="spp";paymentChecks=0;load(true);}}
    @Override protected void onPause(){foreground=false;main.removeCallbacks(foregroundRefresh);main.removeCallbacks(paymentPoll);super.onPause();}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("screen",screen);state.putString("student",studentId);state.putString("from",from);state.putString("to",to);state.putInt("year",calendarYear);}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);io.shutdownNow();brandImages.close();super.onDestroy();}
